/**
 * Archive Dropdown Module
 * 
 * Provides month/year archive navigation via dropdown select.
 * Navigates to dedicated archive pages showing posts from selected period.
 * Auto-selects current archive when viewing an archive page.
 * 
 * @module archive-dropdown
 * @requires #archive-dropdown select element in sidebar
 * @see /blog/archive/YYYY-MM/ for archive page structure
 * 
 * @example
 * // HTML structure (generated by Hugo):
 * // <select id="archive-dropdown">
 * //   <option value="">All Posts</option>
 * //   <option value="/blog/archive/2024-01/">January 2024 (5)</option>
 * // </select>
 */

/**
 * Initializes archive dropdown navigation
 * Handles dropdown selection and pre-selects current archive
 * 
 * @function initArchive
 * @returns {void}
 */

export function initArchive() {
    const archiveDropdown = document.getElementById('archive-dropdown');
    if (!archiveDropdown) return;
    
    // Navigate to selected archive on change
    archiveDropdown.addEventListener('change', function() {
        if (this.value) {
            window.location.href = this.value;
        }
    });
    
    // Pre-select current archive if viewing an archive page
    const currentPath = window.location.pathname;
    if (currentPath.includes('/archive/')) {
        Array.from(archiveDropdown.options).forEach((option, i) => {
            if (option.value && currentPath.includes(option.value)) {
                archiveDropdown.selectedIndex = i;
            }
        });
    }
}